#!/bin/bash
# Mac test (wiring) of Spotlight over the Stage Manager engine's windows keeping its keyboard (1.7.0, statusbar/SMSpotKeyboard.h): while Spotlight's
# overlay is up and not being dismissed, a switcher transition that leaves the stage as it was does not hand the stage's front window the user focus
# (-[SBMainSwitcherControllerCoordinator _focusNewlyAddedApplicationIfNeededTransitioningFromLayoutState:toLayoutState:windowScene:], 17.5.1: the
# focus went to the window's app and Spotlight's keyboard went away); everything else stays Apple's.
set -e
cd "$(dirname "$0")"
fails=0
check() { if eval "$2"; then echo "PASS  $1"; else echo "FAIL  $1"; fails=1; fi; }
H=../statusbar/SMSpotKeyboard.h; S=../statusbar/StatusBar.x; R=crashmap-rules.txt
check "StatusBar.x includes it and the engine's self-check installs it, as an optional part" "grep -q '^#include \"SMSpotKeyboard.h\"' $S && awk '/^static void DMSMSelfCheck/,/^}/' $S | grep -q '^        DMSMSpotKeyboardInstall();'"
check "the hook goes in only for the switcher's own method with the signature read on 17.5.1 (void; from, to, window scene)" "awk '/^static void DMSMSpotKeyboardInstall/,/^}/' $H | grep -q '_focusNewlyAddedApplicationIfNeededTransitioningFromLayoutState:toLayoutState:windowScene:' && awk '/^static void DMSMSpotKeyboardInstall/,/^}/' $H | grep -q 'DMSMExpect(@encode(void), @encode(id), @encode(id), @encode(id), NULL)'"
check "a method missing or of another signature leaves Apple's way (returns before the hook)" "awk '/^static void DMSMSpotKeyboardInstall/,/^}/' $H | awk '/isEqualToString:DMSMExpect/{f=1} f && /return;/{print \"ok\"; exit}' | grep -q ok && awk '/^static void DMSMSpotKeyboardInstall/,/^}/' $H | tail -3 | grep -q 'MSHookMessageEx(c, sel, (IMP)DMSMSpotFocusNew'"
check "kept only with our engine, no kill switch, Spotlight's overlay up on this transition's screen, not being dismissed, the stage as it was" "grep -q 'BOOL spot = DMSMEngine() && !DMTestFlag(\"/tmp/msb-sm-nospotkb\") && DMSpotlightShownOn(screen);' $H && grep -q 'BOOL keep = spot && !DMSMOverlayGoing() && DMSMSameStage(from, to);' $H"
check "the screen is the transition's own window scene (an external display's stage keeps Apple's focus while Spotlight is up on the iPad); not a scene: any screen" "awk '/^static void DMSMSpotFocusNew/,/^}/' $H | grep -q 'UIWindowScene \*screen = \[windowScene isKindOfClass:\[UIWindowScene class\]\] ? windowScene : nil;' && awk '/^static BOOL DMSpotlightShownOn/,/^}/' $S | grep -q '(!scene || w.windowScene == scene)' && grep -q '^static BOOL DMSpotlightShown(void) { return DMSpotlightShownOn(nil); }' $S"
check "kept = Apple's focus call left out; everything else = Apple's call" "awk '/^static void DMSMSpotFocusNew/,/^}/' $H | awk '/if \\(keep\\) \\{/{k=1} k && /return;/{r=1} r && /o_SMSpotFocusNew\\(self, _cmd, from, to, windowScene\\);/{print \"ok\"; exit}' | grep -q ok"
check "being dismissed = either of SpringBoard's transient overlay dismissals is the workspace's transaction (its own, and the one an app's transition asks for)" "awk '/^static BOOL DMSMOverlayGoing/,/^}/' $H | grep -q '@\"SBTransientOverlayDismissWorkspaceTransaction\", @\"SBTransientOverlayDismissToAppsWorkspaceTransaction\"' && awk '/^static BOOL DMSMOverlayGoing/,/^}/' $H | grep -q 'currentTransaction' && awk '/^static BOOL DMSMOverlayGoing/,/^}/' $H | grep -q 'isKindOfClass:going'"
check "the engine's own re-placements wait while Spotlight is up (a turn's, Fit's re-tiling): a request then is Spotlight's dismissal" "grep -q '^static BOOL DMSMSpotlightHolds(void) { return DMSMEngine() && DMSpotlightShown(); }' $S && awk '/^static void DMSMWatchTurn/,/^}/' $S | grep -q 'if ((DMSMSpotlightHolds() || (spotWaits && DMSMWorkspaceBusy())) && spotWaits < 1200)' && awk '/^static void DMSMFitTick\\(BOOL force\\) \\{/,/^}/' $S | grep -q 'if (DMSMSpotlightHolds()) { if (force) forceWaiting = YES; return; }'"
check "the stage as it was = both layout states' app layouts there and equal (a window added or moved: Apple's way)" "awk '/^static BOOL DMSMSameStage/,/^}/' $H | grep -q 'return a && b && \\[a isEqual:b\\];' && awk '/^static BOOL DMSMSameStage/,/^}/' $H | grep -q 'DMSMSigOK(from, al, DMSMSigObj(), \"appLayout\")'"
check "Fit's set counts every turn: turned and back while it waited (under Spotlight) is laid out again for this shape" "awk '/^static BOOL DMSMTurnSettling\\(void\\) \\{/,/^}/' $S | grep -q 'if (lastScr.width > 0.0) { gSMTurnAt = now; gSMTurns++; }' && awk '/^static void DMSMFitTick\\(BOOL force\\) \\{/,/^}/' $S | grep -q 'arrayByAddingObject:\\[NSString stringWithFormat:@\"%@ turn %u\", NSStringFromCGSize(\\[UIScreen mainScreen\\].bounds.size), gSMTurns\\]\\]'"
check "every function is a DMSM one, which the crash map gives to windowingEnabled" "! grep -E '^static [A-Za-z (*]+[A-Za-z_]+\\(' $H | grep -v -E '^static [A-Za-z (*]+(DMSM[A-Z][A-Za-z]*|o_SMSpotFocusNew)\\(' | grep -q . && grep -q '^sym MacStatusBarCore \\^_\\*DMSM\\[A-Z0-9\\] windowingEnabled' $R"
check "the debug tracer of the focus requests is in debug builds only" "awk '/^static void DMKBTraceStart/{print NR; exit}' $S | xargs -I{} awk -v n={} 'NR<n && /^#if DEBUG\$/{d=NR} NR<n && /^#endif/{e=NR} END{exit !(d>e)}' $S"
[ $fails = 0 ] && echo "test-smspotkb: all wiring checks pass" || { echo "test-smspotkb: wiring checks FAILED"; exit 1; }
